INSERT INTO "pages" ("id", "nav_id", "datetime", "title", "description", "logo", "content", "content_json", "is_active", "is_delete", "created_at", "updated_at", "rss_yandex_id", "is_template", "template_id", "css") VALUES (11, 1, '2026-09-24 09:49:40.331017', 'Космологическая сингулярность', 'Начало и пределы описания', '/static/core/engine/lib/word/editor/images/files/img-1c4c06ce.svg', '<body><div class="flex-shell"><nav id="i7u9" class="flex-shell__nav effect-c7a2">Космос</nav><main class="flex-shell__main"><aside class="flex-shell__area flex-shell__area--left effect-a3f7"><svg viewBox="0 0 200 320" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Звёздное небо" class="effect-a3f7__art"><circle cx="18" cy="24" r="1.2" opacity="0.9"></circle><circle cx="52" cy="14" r="0.9" opacity="0.6"></circle><circle cx="88" cy="30" r="1.4" opacity="0.8"></circle><circle cx="126" cy="18" r="1" opacity="0.5"></circle><circle cx="164" cy="36" r="1.2" opacity="0.75"></circle><circle cx="190" cy="12" r="0.8" opacity="0.45"></circle><circle cx="30" cy="60" r="1" opacity="0.55"></circle><circle cx="70" cy="74" r="1.3" opacity="0.85"></circle><circle cx="110" cy="58" r="0.9" opacity="0.5"></circle><circle cx="150" cy="80" r="1.1" opacity="0.7"></circle><circle cx="186" cy="64" r="1.3" opacity="0.8"></circle><circle cx="12" cy="104" r="1.1" opacity="0.65"></circle><circle cx="46" cy="120" r="0.9" opacity="0.5"></circle><circle cx="86" cy="108" r="1.4" opacity="0.9"></circle><circle cx="124" cy="130" r="1" opacity="0.55"></circle><circle cx="162" cy="114" r="0.9" opacity="0.45"></circle><circle cx="194" cy="126" r="1.2" opacity="0.7"></circle><circle cx="26" cy="168" r="1" opacity="0.6"></circle><circle cx="64" cy="182" r="1.3" opacity="0.8"></circle><circle cx="104" cy="166" r="0.9" opacity="0.5"></circle><circle cx="142" cy="190" r="1.1" opacity="0.7"></circle><circle cx="180" cy="172" r="1" opacity="0.55"></circle><circle cx="14" cy="226" r="1.2" opacity="0.75"></circle><circle cx="54" cy="240" r="0.9" opacity="0.5"></circle><circle cx="94" cy="222" r="1.4" opacity="0.85"></circle><circle cx="132" cy="248" r="1" opacity="0.6"></circle><circle cx="170" cy="230" r="0.9" opacity="0.45"></circle><circle cx="196" cy="256" r="1.1" opacity="0.65"></circle><circle cx="24" cy="286" r="1" opacity="0.55"></circle><circle cx="66" cy="300" r="1.3" opacity="0.8"></circle><circle cx="108" cy="282" r="0.9" opacity="0.5"></circle><circle cx="148" cy="306" r="1.2" opacity="0.7"></circle><circle cx="188" cy="292" r="1" opacity="0.55"></circle><path d="M0,-7 L1.4,-1.4 L7,0 L1.4,1.4 L0,7 L-1.4,1.4 L-7,0 L-1.4,-1.4 Z" transform="translate(96,108)" opacity="0.9"></path><path d="M0,-6 L1.2,-1.2 L6,0 L1.2,1.2 L0,6 L-1.2,1.2 L-6,0 L-1.2,-1.2 Z" transform="translate(70,74)" opacity="0.7"></path><path d="M0,-5 L1,-1 L5,0 L1,1 L0,5 L-1,1 L-5,0 L-1,-1 Z" transform="translate(170,230)" opacity="0.55"></path></svg></aside><section class="flex-shell__area flex-shell__area--center"><div data-slot="content"><h2>Космологическая сингулярность: начало и пределы описания</h2><p>Космологическая сингулярность — это состояние Вселенной в начальный момент её расширения, при котором плотность энергии и температура вещества формально стремятся к бесконечности, а известные физические теории теряют применимость. Представление о сингулярности возникает как предельный случай решения уравнений общей теории относительности при обратном ходе времени: если расширение Вселенной продолжать мысленно в прошлое, масштабный фактор стремится к нулю, а кривизна пространства-времени неограниченно возрастает.</p><h3>Историческая основа</h3><p>Первые модели такой эволюции были предложены в 1920-х годах в работах Александра Фридмана, описавшего нестационарные решения уравнений Эйнштейна. Жорж Леметр связал эти решения с представлением о «первичном атоме», а дальнейшие наблюдения красного смещения галактик Эдвином Хабблом подтвердили, что Вселенная действительно расширяется. Теоремы о сингулярности, сформулированные Роджером Пенроузом и Стивеном Хокингом в 1960-х годах, показали, что сингулярность не является артефактом идеализированной симметричной модели, а следует из достаточно общих предположений о гравитационном поле и распределении материи.</p><h3>Физический смысл и ограничения теории</h3><p>Важно понимать, что сингулярность — не физический объект, который можно наблюдать, а указание на границу применимости классической теории гравитации. Вблизи планковских масштабов, порядка 10<sup>−43</sup> секунды и 10<sup>−35</sup> метра, квантовые эффекты должны становиться существенными, и описание требует объединения общей теории относительности с квантовой механикой. Именно поэтому современные подходы рассматривают сингулярность не как абсолютное начало, а как предел, за которым необходима новая теория.</p><h3>Современные подходы</h3><p>Инфляционная космология предполагает, что наблюдаемому горячему расширению предшествовала фаза ускоренного раздувания, что позволяет объяснить однородность и плоскостность Вселенной, не обращаясь напрямую к бесконечным величинам. Квантовая гравитация, включая теорию струн и петлевую квантовую гравитацию, исследует сценарии, в которых сингулярность заменяется состоянием с конечной кривизной — так называемым отскоком. Циклические и мультивселенные модели также рассматривают возможность того, что наблюдаемая фаза расширения является лишь одним из этапов более общей эволюции.</p><h3>Наблюдательные свидетельства</h3><p>Прямых наблюдений сингулярности не существует и принципиально быть не может, поскольку она относится к области, недоступной для сигналов. Косвенные основания дают реликтовое излучение, распространённость лёгких элементов и крупномасштабная структура Вселенной: все эти данные согласуются с моделью горячего Большого взрыва, возраст которой оценивается примерно в 13,8 миллиарда лет. Именно совокупность этих свидетельств делает представление о начальном горячем плотном состоянии основой современной космологии, несмотря на сохраняющуюся неполноту теоретического описания.</p></div></section><aside id="i9mwl" class="flex-shell__area flex-shell__area--right effect-r5oq1"><svg viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false" class="effect-r5oq1__art"><g fill="var(--theme-text, #ffffff)"><circle cx="24" cy="30" r="1.6"></circle><circle cx="58" cy="14" r="1"></circle><circle cx="92" cy="38" r="1.3"></circle><circle cx="140" cy="20" r="1.1"></circle><circle cx="176" cy="46" r="1.7"></circle><circle cx="16" cy="86" r="1.1"></circle><circle cx="46" cy="118" r="1.4"></circle><circle cx="110" cy="72" r="1"></circle><circle cx="166" cy="104" r="1.2"></circle><circle cx="34" cy="164" r="1.3"></circle><circle cx="84" cy="150" r="1"></circle><circle cx="130" cy="176" r="1.4"></circle><circle cx="186" cy="150" r="1"></circle></g><circle cx="100" cy="100" r="34" fill="var(--theme-accent, #7c9cff)"></circle><circle cx="88" cy="90" r="7" fill="var(--theme-bg, #0b0e1a)" opacity="0.35"></circle><circle cx="112" cy="118" r="5" fill="var(--theme-bg, #0b0e1a)" opacity="0.3"></circle><ellipse cx="100" cy="108" rx="62" ry="18" fill="none" stroke="var(--theme-accent, #7c9cff)" stroke-width="1.5" opacity="0.6" transform="rotate(-18 100 108)"></ellipse></svg></aside></main><footer class="flex-shell__footer">Footer</footer></div></body>', '{"assets":[{"type":"image","src":"/media/default/1_2a5d0981.jpg","unitDim":"px","height":0,"width":0,"name":"1_2a5d0981.jpg"},{"type":"image","src":"/media/default/deepseek_mermaid_20260714_ea7f08_552fde3a.png","unitDim":"px","height":0,"width":0,"name":"deepseek_mermaid_20260714_ea7f08_552fde3a.png"},{"type":"image","src":"/media/default/logo_ec0d8ede.png","unitDim":"px","height":0,"width":0,"name":"logo_ec0d8ede.png"}],"styles":[{"selectors":[],"selectorsAdd":"*","style":{"box-sizing":"border-box"}},{"selectors":[],"selectorsAdd":"body","style":{"margin-top":"0px","margin-right":"0px","margin-bottom":"0px","margin-left":"0px"}},{"sele