in: 0;}*{box-sizing:border-box;}body{margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;}.effect-a7k3{position:relative;overflow-x:hidden;overflow-y:hidden;}.effect-a7k3::before{content:"";position:absolute;top:0px;right:0px;bottom:0px;left:0px;pointer-events:none;z-index:0;opacity:0.6;filter:blur(2.5px);background-repeat:repeat;background-image:linear-gradient(104deg, transparent 44%, color-mix(in srgb, var(--theme-accent, #ffffff) 70%, transparent) 50%, transparent 56%),
