    font-weight: var(--theme-font-weight-semibold);
    line-height: 1.2;
    text-decoration: none;
    text-align: center;
    white-space: nowrap;
    cursor: pointer;
    background: var(--theme-accent);
    color: var(--theme-text-invert);
    border-color: var(--theme-accent);
    transition: background 0.15s ease, border-color 0.15s ease, transform 0.1s ease;
}

.core-engine-lib-word-blocks .btn:hover {
    background: var(--theme-accent-hover);
    border-color: var(--theme-accent-hover);
    color: var(--theme-text-invert);
}

.core-engine-lib-word-blocks .btn:active {
    transform: translateY(1px);
}

.core-engine-lib-word-blocks .btn--ghost {
    background: transparent;
    color: var(--theme-accent);
    border-color: var(--theme-accent);
}

.core-engine-lib-word-blocks .btn--ghost:hover {
    background: var(--theme-accent-soft);
    color: var(--theme-accent);
    border-color: var(--theme-accent);
}


/* ============================================
   CARD
   ============================================ */

.core-engine-lib-word-blocks .card {
    padding: var(--theme-space-6);
    background: var(--theme-bg);
    border: 1px solid var(--theme-border);
    border-radius: var(--theme-radius-lg);
    box-shadow: var(--theme-shadow-sm);
}

.core-engine-lib-word-blocks .card__title {
    margin: 0 0 var(--theme-space-2);
    font-family: var(--theme-font-family);
    font-size: var(--theme-font-size-xl);
    font-weight: var(--theme-font-weight-semibold);
    line-height: var(--theme-line-height-tight);
    color: var(--theme-text);
}

.core-engine-lib-word-blocks .card__text {
    margin: 0;
    font-family: var(--theme-font-family);
    font-size: var(--theme-font-size-base);
    line-height: var(--theme-line-height-base);
    color: var(--theme-text-muted);
}


/* ============================================
   BADGE
   ============================================ */

.core-engine-lib-word-blocks .badge {
    display: inline-block;
    padding: var(--theme-space-1) var(--theme-space-3);
    border-radius: var(--theme-radius-pill);
    background: var(--theme-accent-soft);
    color: var(--theme-accent);
    font-family: var(--theme-font-family);
    font-size: var(--theme-font-size-sm);
    font-weight: var(--theme-font-weight-medium);
    line-height: 1.4;
}


/* ============================================
   QUOTE
   ============================================ */

.core-engine-lib-word-blocks .quote {
    margin: var(--theme-space-6) 0;
    padding: var(--theme-space-4) var(--theme-space-5);
    border-left: 4px solid var(--theme-accent);
    background: var(--theme-bg-subtle);
    border-radius: 0 var(--theme-radius-md) var(--theme-radius-md) 0;
    font-family: var(--theme-font-family);
    font-size: var(--theme-font-size-lg);
    font-style: italic;
    line-height: var(--theme-line-height-loose);
    color: var(--theme-text-muted);
}


/* ============================================
   IMAGE
   ============================================ */

.core-engine-lib-word-blocks .image {
    display: block;
    max-width: 100%;
    height: auto;
    border-radius: var(--theme-radius-md);
    margin: 0;
}


/* ============================================
   ICON
   ============================================ */

.core-engine-lib-word-blocks .icon {
    display: inline-block;
    width: 1.5em;
    height: 1.5em;
    vertical-align: middle;
    color: var(--theme-accent);
    flex-shrink: 0;
}


/* ============================================
   DIVIDER
   ============================================ */

.core-engine-lib-word-blocks .divider {
    margin: var(--theme-space-8) 0;
    border: none;
    height: 1px;
    background: var(--theme-border);
}


/* ============================================
   SECTION — vertical rhythm wrapper
   ============================================ */

.core-engine-lib-word-blocks .section {
    padding-top: var(--theme-space-section);
    padding-bottom: var(--theme-space-section);
}


/* ============================================
   CONTAINER — centered max-width wrapper
   ============================================ */

.core-engine-lib-word-blocks .container {
    width: 100%;
    max-width: var(--theme-container-max);
    margin-left: auto;
    margin-right: auto;
    padding-left: var(--theme-space-gutter);
    padding-right: var(--theme-space-gutter);
    box-sizing: border-box;
}


/* ============================================
   GRID — base
   ============================================ */

.core-engine-lib-word-blocks .grid {
    display: grid;
    gap: var(--theme-space-grid);
}

.core-engine-lib-word-blocks .grid--2 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}

.core-engine-lib-word-blocks .grid--3 {
    grid-template-columns: repeat(3, minmax(0, 1fr));
}

.core-engine-lib-word-blocks .grid--4 {
    grid-template-columns: repeat(4, minmax(0, 1fr));
}

.core-engine-lib-word-blocks .grid--auto {
    grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));
}


/* ============================================
   COLUMN — grid cell
   ============================================ */

/*
 * Minimal cell: only prevents overflow. Padding, background, border
 * are set per block (e.g. .card, .col--tile were removed on purpose).
 */
.core-engine-lib-word-blocks .col {
    min-width: 0;
}


/* ============================================
   GRID — responsive fallback
   ============================================ */

@media (max-width: 768px) {
    .core-engine-lib-word-blocks .grid--2,
    .core-engine-lib-word-blocks .grid--3,
    .core-engine-lib-word-blocks .grid--4 {
        grid-template-columns: minmax(0, 1fr);
    }
}

* { box-sizing: border-box; } body {margin: 0;}');
INSERT INTO "pages" ("id", "nav_id", "datetime", "title", "description", "logo", "content", "content_json", "is_active", "is_delete", "created_at", "updated_at", "rss_yandex_id", "is_template", "template_id", "css") VALUES (21, 1, '2026-09-26 22:13:41.769202', 'Приключения Электроника', 'Фанатская страница легендарного фильма', '/static/core/engine/lib/word/editor/images/files/img-663eda4a.svg', '<body id="ik47"><section data-block="core-hero" id="ifh8-2" class="section hero fx-festive-ribbons"><div class="container hero__inner"><h1 class="h1 hero__title">Приключения Электроника</h1><p class="lead hero__lead">Фанатская страница легендарного трёхсерийного телефильма 1979 года: мальчик-робот, школьные будни и песни, которые знают наизусть несколько поколений.</p><a href="page:about" class="btn hero__btn">О фильме</a></div></section><section class="section"><div class="container"><span data-block="core-badge" class="badge">Фанатская страница · 1979 · 3 серии</span></div></section><section class="section"><div class="container"><p data-block="core-lead" class="lead">«Приключения Электроника» — советский телефильм режиссёра Константина Бромберга по повести Евгения Велтистова. Здесь собраны материалы о фильме, его героях, музыке и создателях.</p></div></section><section data-block="core-text-image" class="section text-image fx-soft-diagonal-hatch"><div class="container"><div class="grid grid--2 text-image__grid"><div class="text-image__text"><h2 class="h2">О фильме</h2><p class="text">Семиклассник Сергей Сыроежкин встречает своего двойника — робота Электроника, созданного профессором Громовым. С этого знакомства начинается история о дружбе, ответственности и праве быть собой.</p><p class="text text--muted">Фильм снят в 1979 году на Одесской киностудии; музыку к нему написал композитор Евгений Крылатов.</p></div><div class="text-image__media"><svg viewBox="0 0 800 600" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Кадр из фильма «Приключения Электроника»" class="image"><circle cx="268" cy="240" r="55" fill="var(--theme-text, #1e293b)"></circle><rect x="254" y="286" width="29" height="58" fill="var(--theme-text, #1e293b)"></rect><path d="M201 540 L218 382 Q225 338 268 338 Q311 338 318 382 L335 540 Z" fill="var(--theme-text, #1e293b)"></path><rect x="227" y="538" width="26" height="53" rx="10" fill="var(--theme-text, #1e293b)"></rect><rect x="282" y="538" width="26" height="53" rx="10" fill="var(--theme-text, #1e293b)"></rect><circle cx="520" cy="240" r="55" fill="var(--theme-text, #1e293b)"></circle><rect x="506" y="286" width="29" height="58" fill="var(--theme-text, #1e293b)"></rect><path d="M453 540 L470 382 Q477 338 520 338 Q563 338 570 382 L587 540 Z" fill="var(--theme-text, #1e293b)"></path><rect x="479" y="538" width="26" height="53" rx="10" fill="var(--theme-text, #1e293b)"></rect><rect x="534" y="538" width="26" height="53" rx="10" fill="var(--theme-text, #1e293b)"></rect><path d="M468 235 Q520 135 572 235 Z" fill="var(--theme-accent, #3b82f6)"></path><rect x="445" y="228" width="150" height="18" rx="9" fill="var(--theme-accent, #3b82f6)"></rect></svg></div></div></div></section><section class="section"><div class="container"><h2 data-block="core-heading-h2" class="h2">Интересные факты</h2></div></section><section class="section"><div class="container"><div data-block="core-card" class="card"><h3 class="card__title">Профессор Громов</h3><p class="card__text">Учёный-конструктор, автор Электроника. Убеждён, что техника должна служить человеку.</p></div></div></section><section class="section"><div class="container"><blockquote data-block="core-quote" class="quote">«Приключения Электроника» — история о том, что быть человеком значит уметь дружить, ошибаться и отвечать за тех, кто рядом.</blockquote></div></section><section data-block="core-features" class="section features fx-office-grid"><div class="container"><h2 class="h2 features__title">Чем запомнился фильм</h2><div class="grid grid--3 features__grid"><div class="card features__item"><h3 class="card__title">Музыка Евгения Крылатова</h3><p class="card__text">Песни «Крылатые качели» и «Мы — маленькие дети» на стихи Юрия Энтина давно живут отдельно от фильма.</p></div><div class="card features__item"><h3 class="card__title">Двойная роль</h3><p class="card__text">Сергея и Электроника сыграли братья-близнецы Юрий и Владимир Торсуевы — благодаря их сходству эффект двойника выглядит достоверно.</p></div><div class="card features__item"><h3 class="card__title">Разговор о главном</h3><p class="card__text">За внешней фантастикой прячется серьёзный разговор о честности, дружбе и ответственности за свои поступки.</p></div></div></div></section><section class="section"><div class="container"><h2 data-block="core-heading-h2" class="h2">Интересные факты</h2></div></section><section class="section fx-school-notebook"><div class="container"><ol data-block="core-list-num" class="list list--num"><li>Фильм снят по повести Евгения Велтистова «Электроник — мальчик из чемодана».</li><li>Съёмки проходили в Одессе и Москве, а школьные сцены снимали в реальных зданиях.</li><li>Музыку к фильму написал Евгений Крылатов, тексты песен — Юрий Энтин.</li></ol></div></section><section data-block="core-gallery" class="section gallery fx-circles-n"><div class="container"><h2 class="h2 gallery__title">Кадры из фильма</h2><div class="grid grid--auto gallery__grid"><svg viewBox="0 0 800 600" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Кадр: Электроник у школьного здания" class="image gallery__item"><polygon points="210,182 440,86 670,182" fill="var(--theme-accent, #3b82f6)"></polygon><rect x="230" y="180" width="420" height="300" fill="var(--theme-bg-soft, #f1f5f9)" stroke="var(--theme-text-muted, #94a3b8)" stroke-width="5"></rect><rect x="265" y="212" width="60" height="60" fill="var(--theme-accent, #3b82f6)"></rect><rect x="365" y="212" width="60" height="60" fill="var(--theme-accent, #3b82f6)"></rect><rect x="465" y="212" width="60" height="60"