INSERT INTO "pages" ("id", "nav_id", "datetime", "title", "description", "logo", "content", "content_json", "is_active", "is_delete", "created_at", "updated_at", "rss_yandex_id", "is_template", "template_id", "css") VALUES (28, 1, '2026-09-27 13:42:25.496052', 'Музыкальная студия полного цикла', 'Запись, сведение и мастеринг в профессионально оборудованных залах', '/static/core/engine/lib/word/editor/images/files/img-d156c83e.svg', '<body id="i7mq"><section data-block="core-hero" class="section hero fx-music-equalizer"><div class="container hero__inner"><h1 class="h1 hero__title" id="iggo">Музыкальная студия полного цикла</h1><p class="lead hero__lead">Запись, сведение и мастеринг в профессионально оборудованных залах. Помогаем артистам, группам и проектам получить готовый трек от идеи до релиза.</p><a href="page:contacts" class="btn hero__btn">Записаться на сессию</a></div></section><section data-block="core-features" class="section features fx-vinyl-grooves"><div class="container"><h2 class="h2 features__title">Преимущества</h2><div class="grid grid--3 features__grid"><div class="card features__item"><h3 class="card__title">Профессиональное оборудование</h3><p class="card__text">Запись ведётся на студийные микрофоны, предусилители и аналоговые приборы обработки звука.</p></div><div class="card features__item"><h3 class="card__title">Опытные звукорежиссёры</h3><p class="card__text">Команда специалистов с опытом работы над релизами разных жанров — от попа до джаза.</p></div><div class="card features__item"><h3 class="card__title">Гибкий график сессий</h3><p class="card__text">Бронируйте студию на удобное время, включая вечерние часы и выходные дни.</p></div></div></div></section><section data-block="core-steps" class="section steps fx-faint-equalizer-lines"><div class="container"><h2 class="h2 steps__title">Как это работает</h2><div class="grid grid--3 steps__grid"><div class="steps__item"><div class="steps__num">1</div><h3 class="h3 steps__item-title">Заявка на запись</h3><p class="text text--muted">Оставьте заявку, укажите формат проекта и удобные даты. Мы согласуем дату и время сессии.</p></div><div class="steps__item"><div class="steps__num">2</div><h3 class="h3 steps__item-title">Студийная сессия</h3><p class="text text--muted">Звукорежиссёр готовит зал и оборудование, проводит запись вокала и инструментов.</p></div><div class="steps__item"><div class="steps__num">3</div><h3 class="h3 steps__item-title">Сведение и мастеринг</h3><p class="text text--muted">Сводим материал, выполняем мастеринг и передаём готовые файлы в нужном формате.</p></div></div></div></section><section data-block="core-text-image" class="section text-image"><div class="container"><div class="grid grid--2 text-image__grid"><div class="text-image__text"><h2 class="h2">О студии</h2><p class="text">Мы предлагаем запись вокала и инструментов, сведение, мастеринг и репетиционные залы с акустической подготовкой.</p><p class="text text--muted">Работаем с артистами, группами, подкастами, рекламными и кино-проектами. Помогаем с аранжировкой и подбором сессионных музыкантов.</p></div><div class="text-image__media"><svg viewBox="0 0 800 600" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Микшерный пульт и студийный мониторинг в аппаратной музыкальной студии" class="image"><rect x="90" y="150" width="140" height="215" rx="12" fill="var(--theme-text, #1e293b)"></rect><circle cx="160" cy="288" r="42" fill="var(--theme-bg-soft, #f1f5f9)"></circle><circle cx="160" cy="288" r="15" fill="var(--theme-text-muted, #94a3b8)"></circle><circle cx="160" cy="206" r="19" fill="var(--theme-bg-soft, #f1f5f9)"></circle><rect x="570" y="150" width="140" height="215" rx="12" fill="var(--theme-text, #1e293b)"></rect><circle cx="640" cy="288" r="42" fill="var(--theme-bg-soft, #f1f5f9)"></circle><circle cx="640" cy="288" r="15" fill="var(--theme-text-muted, #94a3b8)"></circle><circle cx="640" cy="206" r="19" fill="var(--theme-bg-soft, #f1f5f9)"></circle><rect x="115" y="365" 