INSERT INTO "pages" ("id", "nav_id", "datetime", "title", "description", "logo", "content", "content_json", "is_active", "is_delete", "created_at", "updated_at", "rss_yandex_id", "is_template", "template_id", "css") VALUES (37, 1, '2026-09-30 19:34:57.798917', 'Статья 1', '', '', '<body><section data-block="core-hero" class="section hero fx-confetti-fall" id="i9g9"><div class="container hero__inner"><h1 class="h1 hero__title">Картины художников Урала</h1><p class="lead hero__lead">Выставка живописи уральских мастеров XVIII–XXI веков: горнозаводские пейзажи, портреты, бытовые сцены и индустриальные мотивы. Более 120 произведений из музейных и частных собраний.</p><a href="#" class="btn hero__btn">Купить билет</a></div></section><section class="section fx-soft-diagonal-hatch"><div class="container"><p data-block="core-lead" class="lead">Экспозиция прослеживает, как менялся образ Урала в отечественной живописи: от классических видов горнозаводского края до индустриального пейзажа и современного художественного высказывания. Выставка работает с 12 марта по 30 июня 2025 года в главном корпусе музея.</p></div></section><section data-block="core-text-image" class="section text-image fx-aurora-weave"><div class="container"><div class="grid grid--2 text-image__grid"><div class="text-image__text"><h2 class="h2">О выставке</h2><p class="text">В основе экспозиции — произведения уральских живописцев из фондов музея и частных коллекций. Посетители увидят работы Алексея Денисова-Уральского, Леонарда Туржанского, Ивана Слюсарева и современных авторов Екатеринбурга, Нижнего Тагила и Перми.</p><p class="text text--muted">Экспозиция дополнена архивными фотографиями, документами и предметами горнозаводского быта, которые помогают увидеть исторический контекст представленных полотен.</p></div><div class="text-image__media"><svg viewBox="0 0 800 600" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Экспозиция живописи уральских мастеров в зале музея" class="image"><rect x="120" y="80" width="560" height="440" fill="var(--theme-bg-soft, #f1f5f9)" stroke="var(--theme-text, #1e293b)" stroke-width="4"></rect><rect x="160" y="120" width="180" height="240" fill="var(--theme-accent, #3b82f6)" opacity="0.7"></rect><rect x="380" y="120" width="180" height="240" fill="var(--theme-accent, #3b82f6)" opacity="0.5"></rect><rect x="600" y="120" width="60" height="240" fill="var(--theme-accent, #3b82f6)" opacity="0.3"></rect><rect x="160" y="400" width="500" height="80" fill="var(--theme-text-muted, #94a3b8)" opacity="0.4"></rect><circle cx="280" cy="480" r="18" fill="var(--theme-text, #1e293b)" opacity="0.6"></circle><circle cx="400" cy="480" r="18" fill="var(--theme-text, #1e293b)" opacity="0.6"></circle><circle cx="520" cy="480" r="18" fill="var(--theme-text, #1e293b)" opacity="0.6"></circle><rect x="240" y="460" width="80" height="40" rx="4" fill="var(--theme-text, #1e293b)" opacity="0.3"></rect><rect x="360" y="460" width="80" height="40" rx="4" fill="var(--theme-text, #1e293b)" opacity="0.3"></rect><rect x="480" y="460" width="80" height="40" rx="4" fill="var(--theme-text, #1e293b)" opacity="0.3"></rect></svg></div></div></div></section><section data-block="core-gallery" class="section gallery fx-vinyl-grooves"><div class="container"><h2 class="h2 gallery__title">Галерея экспозиции</h2><div class="grid grid--auto gallery__grid"><svg viewBox="0 0 800 600" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Горнозаводской пейзаж уральского художника" class="image gallery__item"><rect x="60" y="80" width="680" height="440" rx="6" fill="var(--theme-bg-soft, #f1f5f9)" stroke="var(--theme-text, #1e293b)" stroke-width="6"></rect><path d="M120 420 L260 240 L360 340 L470 180 L620 420 Z" fill="var(--theme-accent, #3b82f6)" opacity="0.85"></path><path d="M120 420 L260 240 L360 340 L470 180 L620 420 Z" fill="none" stroke="var(--theme-text, #1e293b)" stroke-width="5"></path><rect x="150" y="300" width="70" height="120" fill="var(--theme-text-muted, #94a3b8)"></rect><rect x="150" y="300" width="70" height="120" fill="none" stroke="var(--theme-text, #1e293b)" stroke-width="4"></rect><rect x="175" y="250" width="20" height="50" fill="var(--theme-text-muted, #94a3b8)"></rect><rect x="500" y="330" width="90" height="90" fill="var(--theme-text-muted, #94a3b8)"></rect><rect x="500" y="330" width="90" height="90" fill="none" stroke="var(--theme-text, #1e293b)" stroke-width="4"></rect><path d="M545 330 L545 280 L575 280 L575 330" fill="var(--theme-text-muted, #94a3b8)" stroke="var(--theme-text, #1e293b)" stroke-width="4"></path><circle cx="660" cy="150" r="38" fill="var(--theme-accent, #3b82f6)" opacity="0.7"></circle><path d="M120 420 L620 420" stroke="var(--theme-text, #1e293b)" stroke-width="5"></path></svg><svg viewBox="0 0 800 600" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Портрет работы уральского живописца" class="image gallery__item"><rect x="250" y="80" width="300" height="440" rx="6" fill="var(--theme-bg-soft, #f1f5f9)" stroke="var(--theme-text, #1e293b)" stroke-width="4"></rect><circle cx="400" cy="240" r="70" fill="var(--theme-accent, #3b82f6)"></circle><path d="M300 460 Q400 340 500 460 Z" fill="var(--theme-accent, #3b82f6)"></path><rect x="330" y="120" width="140" height="10" rx="5" fill="var(--theme-text-muted, #94a3b8)"></rect><rect x="360" y="145" width="80" height="8" rx="4" fill="var(--theme-text-muted, #94a3b8)"></rect></svg><svg viewBox="0 0 800 600" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Бытовая сцена из жизни горнозаводского Урала" class="image gallery__item"><rect x="120" y="330" width="560" height="30" fill="var(--theme-bg-soft, #f1f5f9)"></rect><rect x="150" y="360" width="20" height="120" fill="var(--theme-text-muted, #94a3b8)"></rect><rect x="630" y="360" width="20" height="120" fill="var(--theme-text-muted, #94a3b8)"></rect><rect x="150" y="360" width="500" height="12" fill="var(--theme-text-muted, #94a3b8)"></rect><rect x="200" y="300" width="90" height="30" fil