radius:24px;border-bottom-right-radius:24px;border-bottom-left-radius:24px;padding-top:28px;padding-right:24px;padding-bottom:28px;padding-left:24px;text-align:center;box-shadow:rgba(239, 71, 111, 0.12) 0px 10px 30px;border-top-width:6px;border-top-style:solid;border-top-color:rgb(255, 209, 102);}.fan-tour__date{display:inline-block;padding-top:4px;padding-right:14px;padding-bottom:4px;padding-left:14px;border-top-left-radius:999px;border-top-right-radius:999px;border-bottom-right-radius:999px;border-bottom-left-radius:999px;background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgb(6, 214, 160);color:rgb(255, 255, 255);font-size:13px;font-weight:600;margin-bottom:12px;}.fan-tour__card h3{margin-top:0px;margin-right:0px;margin-bottom:6px;margin-left:0px;color:rgb(239, 71, 111);font-size:20px;}.fan-tour__card p{margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;color:rgb(74, 74, 90);font-size:14px;}.fan-club{padding-top:80px;padding-right:40px;padding-bottom:80px;padding-left:40px;background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgb(255, 255, 255);text-align:center;}.fan-club__text{max-width:600px;margin-top:0px;margin-right:auto;margin-bottom:32px;margin-left:auto;color:rgb(74, 74, 90);font-size:18px;}.fan-club__form{display:flex;row-gap:12px;column-gap:12px;justify-content:center;flex-wrap:wrap;}.fan-club__input{padding-top:14px;padding-right:20px;padding-bottom:14px;padding-left:20px;border-top-left-radius:999px;border-top-right-radius:999px;border-bottom-right-radius:999px;border-bottom-left-radius:999px;border-top-width:2px;border-right-width:2px;border-bottom-width:2px;border-left-width:2px;border-top-style:solid;border-right-style:solid;border-bottom-style:solid;border-left-style:solid;border-top-color:rgb(255, 209, 102);border-right-color:rgb(255, 209, 102);border-bottom-color:rgb(255, 209, 102);border-left-color:rgb(255, 209, 102);border-image-source:initial;border-image-slice:initial;border-image-width:initial;border-image-outset:initial;border-image-repeat:initial;font-size:16px;outline-color:initial;outline-style:none;outline-width:initial;min-width:260px;font-family:inherit;background-image:initial;background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:rgb(255, 253, 247);}.fan-club__input:focus{border-top-color:rgb(6, 214, 160);border-right-color:rgb(6, 214, 160);border-bottom-color:rgb(6, 214, 160);border-left-color:rgb(6, 214, 160);}.fan-footer{padding-top:32px;padding-right:40px;padding-bottom:32px;padding-left:40px;text-align:center;background-image:linear-gradient(90deg, rgb(255, 209, 102), rgb(239, 71, 111), rgb(6, 214, 160), rgb(17, 138, 178));background-position-x:initial;background-position-y:initial;background-size:initial;background-repeat:initial;background-attachment:initial;background-origin:initial;background-clip:initial;background-color:initial;color:rgb(255, 255, 255);font-weight:600;}.fan-footer p{margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;}@keyframes fan-float{0%, 100%{transform:translateY(0px);}50%{transform:translateY(-14px);}}@media (max-width: 900px){.fan-hero{grid-template-columns:1fr;text-align:center;}.fan-hero__actions{justify-content:center;}.fan-about__stats{grid-template-columns:repeat(2, 1fr);}.fan-members__grid{grid-template-columns:repeat(2, 1fr);}.fan-tour__grid{grid-template-columns:repeat(2, 1fr);}.fan-header{flex-direction:column;row-gap:12px;column-gap:12px;}}@media (max-width: 520px){.fan-hero__title{font-size:36px;}.fan-about__stats{grid-template-columns:1fr;}.fan-members__grid{grid-template-columns:1fr;}.fan-tour__grid{grid-template-columns:1fr;}.fan-header__nav{flex-wrap:wrap;justify-content:center;}}');
INSERT INTO "pages" ("id", "nav_id", "datetime", "title", "description", "logo", "content", "content_json", "is_active", "is_delete", "created_at", "updated_at", "rss_yandex_id", "is_template", "template_id", "css") VALUES (39, 1, '2026-09-30 19:52:20.190860', 'Кофе, который согревает', 'Даже в самый хмурый день', '/static/core/engine/lib/word/editor/images/files/img-233bfba6.svg', '<body><section class="hero fx-confetti-fall" id="ikdk"><div class="hero__inner"><div class="hero__content"><p class="hero__eyebrow">Кофейня «Тёплый угол»</p><h1 class="hero__title" id="idkk">Кофе, который согревает даже в самый хмурый день</h1><p class="hero__lead" id="ii6yh">Обжариваем зёрна каждую неделю, печём круассаны с утра и варим капучино, за которым хочется возвращаться. Заходите — у нас всегда пахнет домом.</p><div class="hero__actions"><a href="#menu" class="hero__button hero__button--primary">Смотреть меню</a><a href="#contact" class="hero__button hero__button--ghost" id="ivvak">Как нас найти</a></div><ul class="hero__facts"><li class="hero__fact"><span class="hero__fact-value">12</span><span class="hero__fact-label">сортов зерна</span></li><li class="hero__fact"><span class="hero__fact-value">7:30</span><span class="hero__fact-label">открываемся</span></li><li class="hero__fact"><span class="hero__fact-value">4.9</span><span class="hero__fact-label">рейтинг гостей</span></li></ul></div><div class="hero__visual"><div class="hero__placeholder"><svg viewBox="0 0 120 120" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" class="hero__cup"><path d="M28 44h56v22c0 15.5-12.5 28-28 28S28 81.5 28 66V44Z" fill="#F5E9DA"></path><path d="M84 50h8c6.6 0 12 5.4 12 12s-5.4 12-12 12h-8" stroke="#F5E9DA" stroke-width="6" stroke-linecap="round"></path><path d="M24 100h72" stroke="#F5E9DA" stroke-width="6" stroke-linecap="round"></path><path d="M46 30c0-6 6-6 6-12M62 30c0-6 6-6 6-12" stroke="#E8B27D" stroke-width="5" stroke-linecap="round"></path></svg></div></div></div></section><section class="menu"><div class="menu__inner"><h2 class="menu__title">Наше меню</h2><p class="menu__lead">Свежие продукты, авторские рецепты и атмосфера уюта в каждой чашке</p><div class="menu__grid"><div class="menu__card"><div class="menu__icon"><svg width="48" height="48" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M18 8h1a4 4 0 0 1 0 8h-1" stroke="#6F4E37" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"></path><path d="M2 8h16v9a4 4 0 0 1-4 4H6a4 4 0 0 1-4-4V8z" stroke="#6F4E37" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"></path><line x1="6" y1="1" x2="6" y2="4" stroke="#6F4E37" stroke-width="2" stroke-linecap="round"></line><line x1="10" y1="1" x2="10" y2="4" stroke="#6F4E37" stroke-width="2" stroke-linecap="round"></line><line x1="14" y1="1" x2="14" y2="4" stroke="#6F4E37" stroke-width="2" stroke-linecap="round"></line></svg></div><h3 class="menu__card-title">Кофе</h3><p class="menu__card-text">Эспрессо, капучино, латте, раф и авторские напитки на основе свежеобжаренных зёрен</p><span class="menu__price">от 150 ₽</span></div><div class="menu__card"><div class="menu__icon"><svg width="48" height="48" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L2 7l10 5 10-5-10-5z" stroke="#6F4E37" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"></path><path d="M2 17l10 5 10-5" stroke="#6F4E37" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"></path><path d="M2 12l10 5 10-5" stroke="#6F4E37" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"></path></svg></div><h3 class="menu__card-title">Десерты</h3><p class="menu__card-text">Чизкейки, тарты, круассаны и домашняя выпечка — идеально к кофе</p><span class="menu__price">от 180 ₽</span></div><div class="menu__card"><div class="menu__icon"><svg width="48" height="48" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M3 11l19-9-9 19-2-8-8-2z" stroke="#6F4E37" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"></path></svg></div><h3 class="menu__card-title">Завтраки</h3><p class="menu__card-text">Сырники, омлеты, каши и боулы — подаём с 8:00 до 12:00</p><span class="menu__price">от 220 ₽</span></div><div class="menu__card"><div class="menu__icon"><svg width="48" height="48" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="12" cy="12" r="10" stroke="#6F4E37" stroke-width="2"></circle><path d="M12 6v6l4 2" stroke="#6F4E37" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"></path></svg></div><h3 class="menu__card-title">Обеды</h3><p class="menu__card-text">Супы, салаты, паста и горячее — сытно и по-домашнему</p><span class="menu__price">от 290 ₽</span></div></div><div class="menu__cta"><a href="#contact" class="menu__button">Забронировать столик</a></div></div></section><section class="about"><div class="about__inner"><div class="about__content"><span class="about__label">О нашем кафе</span><h2 class="about__title">Место, где рождается вкус</h2><p class="about__lead">Мы открылись в 2014 году с простой идеей — готовить так, как готовили бы для себя. Свежая выпечка каждое утро, зерно собственной обжарки и команда, которая любит своё дело.</p><p class="about__text">Каждое утро наш шеф-повар выбирает продукты на рынке, а бариста настраивает помол под свежую партию зерна. Мы не используем полуфабрикаты и стараемся, чтобы каждый гость чувствовал себя как дома.</p><div class="about__stats"><div class="about__stat"><span class="about__stat-value">10+</span><span class="about__stat-label">лет на кухне</span></div><div class="about__stat"><span class="about__stat-value">48</span><span class="about__stat-label">позиций в меню</span></div><div class="about__stat"><span class="about__stat-value">120k</span><span class="about__stat-label">чашек кофе в год</span></div></div></div><div class="about__visual"><div class="about__placeholder"><svg viewBox="0 0 64 64" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" class="about__icon"><path d="M16 24h28v14a10 10 0 0 1-10 10h-8a10 10 0 0 1-10-10V24Z" stroke="currentColor" stroke-width="3" stroke-linejoin="round"></path><path d="M44 28h4a6 6 0 0 1 0 12h-4" stroke="currentColor" stroke-width="3" stroke-linecap="round"></path><path d="M22 16c0-3 3-3 3-6M32 16c0-3 3-3 3-6M42 16c0-3 3-3 3-6" stroke="currentColor" stroke-width="3" stroke-linecap="round"></path></svg></div><div class="about__badge"><span class="about__badge-value">100%</span><span class="about__badge-label">свежие продукты</span></div></div></div></section><section class="gallery"><div class="gallery__inner"><h2 class="gallery__title">Наша атмосфера</h2><p class="gallery__lead">Загляните в наш уютный мир кофе и выпечки</p><div class="gallery__grid"><div class="gallery__item"><div class="gallery__placeholder gallery__placeholder--1"></div><div class="gallery__overlay"><span class="gallery__caption">Уютный зал</span></div></div><div class="gallery__item"><div class="gallery__placeholder gallery__placeholder--2"></div><div class="gallery__overlay"><span class="gallery__caption">Свежая выпечка</span></div></div><div class="gallery__item"><div class="gallery__placeholder gallery__placeholder--3"></div><div class="gallery__overlay"><span class="gallery__caption">Ароматный кофе</span></div></div><div class="gallery__item"><div class="gallery__placeholder gallery__placeholder--4"></div><div class="gallery__overlay"><span class="gallery__caption">Встречи с друзьями</span></div></div><div class="gallery__item"><div class="gallery__placeholder gallery__placeholder--5"></div><div class="gallery__overlay"><span class="gallery__caption">Работа за чашкой</span></div></div><div class="gallery__item"><div class="gallery__placeholder gallery__placeholder--6"></div><div class="gallery__overlay"><span class="gallery__caption">Вечерний свет</span></div></div></div></div></section><section class="reviews"><div class="reviews__inner"><h2 class="reviews__title">Отзывы гостей</h2><p class="reviews__lead">Мы гордимся тем, что наши гости возвращаются снова и снова. Вот что они говорят о нас.</p><div class="reviews__grid"><div class="reviews__card"><div class="reviews__stars"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z" fill="#D4A373"></path></svg><svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z" fill="#D4A373"></path></svg><svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z" fill="#D4A373"></path></svg><svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z" fill="#D4A373"></path></svg><svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z" fill="#D4A373"></path></svg></div><p class="reviews__text">«Лучший кофе в городе! Атмосфера уютная, персонал приветливый. Круассаны просто тают во рту. Теперь это моё любимое место для завтраков.»</p><div class="reviews__author"><div class="reviews__avatar"></div><div class="reviews__author-info"><span class="reviews__name">Анна Смирнова</span><span class="reviews__role">Постоянный гость</span></div></div></div><div class="reviews__card"><div class="reviews__stars"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z" fill="#D4A373"></path></svg><svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z" fill="#D4A373"></path></svg><svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z" fill="#D4A373"></path></svg><svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z" fill="#D4A373"></path></svg><svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z" fill="#D4A373"></path></svg></div><p class="reviews__text">«Отмечали здесь день рождения. Очень вкусная кухня, особенно десерты. Интерьер стильный, музыка ненавязчивая. Обязательно вернёмся!»</p><div class="reviews__author"><div class="reviews__avatar"></div><div class="reviews__author-info"><span class="reviews__name">Дмитрий Козлов</span><span class="reviews__role">Гость</span></div></div></div><div class="reviews__card"><div class="reviews__stars"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z" fill="#D4A373"></path></svg><svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z" fill="#D4A373"></path></svg><svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z" fill="#D4A373"></path></svg><svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z" fill="#D4A373"></path></svg><svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z" fill="#D4A373"></path></svg></div><p class="reviews__text">«Заказывала кофе с собой — приготовили быстро и очень вкусно. Бариста знает своё дело. Отдельное спасибо за вежливость и улыбки!»</p><div class="reviews__author"><div class="reviews__avatar"></div><div class="reviews__author-info"><span class="reviews__name">Елена Петрова</span><span class="reviews__role">Любитель кофе</span></div></div></div></div></div></section><section class="contact"><div class="contact__inner"><div class="contact__grid"><div class="contact__info"><h2 class="contact__title">Свяжитесь с нами</h2><p class="contact__lead">Забронируйте столик, закажите торт на праздник или просто задайте вопрос — мы всегда рады помочь.</p><ul class="contact__list"><li class="contact__item"><span class="contact__icon"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"></path><circle cx="12" cy="10" r="3"></circle></svg></span><span>ул. Пушкина, 15, Москва</span></li><li class="contact__item"><span class="contact__icon"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-